SELECT CASE WHEN stores.sqft >= 17896 THEN 'high' WHEN stores.sqft >= 4160 THEN 'mid' ELSE 'low' END AS sqft_bucket, CASE WHEN YEAR(stores.opened_date) < 2024 THEN 'before_2024' WHEN YEAR(stores.opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, COUNT(*) AS total_count FROM store_sales LEFT OUTER JOIN products ON store_sales.product_id = products.id LEFT OUTER JOIN stores ON store_sales.store_id = stores.id WHERE store_sales.units BETWEEN 22 AND 36 GROUP BY CASE WHEN stores.sqft >= 17896 THEN 'high' WHEN stores.sqft >= 4160 THEN 'mid' ELSE 'low' END, CASE WHEN YEAR(stores.opened_date) < 2024 THEN 'before_2024' WHEN YEAR(stores.opened_date) = 2024 THEN '2024' ELSE 'after_2024' END;
